-- 104_contractor_scorecard.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_contractor_scorecards(id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,award_id uuid NOT NULL REFERENCES public.project_tender_awards(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),contractor_name text NOT NULL,dimensions jsonb NOT NULL CHECK(jsonb_typeof(dimensions)='array'),overall_score numeric(5,2)NOT NULL CHECK(overall_score BETWEEN 0 AND 100),management_comment text NOT NULL CHECK(btrim(management_comment)<>''AND char_length(management_comment)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number));CREATE UNIQUE INDEX IF NOT EXISTS contractor_scorecard_one_confirmed_idx ON public.project_contractor_scorecards(project_id)WHERE status='CONFIRMED';CREATE OR REPLACE FUNCTION private.prevent_contractor_scorecard_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'CONTRACTOR_SCORECARD_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS contractor_scorecard_immutable ON public.project_contractor_scorecards;CREATE TRIGGER contractor_scorecard_immutable BEFORE UPDATE OR DELETE ON public.project_contractor_scorecards FOR EACH ROW EXECUTE FUNCTION private.prevent_contractor_scorecard_mutation();ALTER TABLE public.project_contractor_scorecards ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS contractor_scorecard_select ON public.project_contractor_scorecards;CREATE POLICY contractor_scorecard_select ON public.project_contractor_scorecards FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_contractor_scorecards FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_contractor_scorecards TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_contractor_scorecard(p_project_id bigint,p_scorecard_id uuid,p_management_comment text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;a public.project_tender_awards%ROWTYPE;c public.project_cost_closeout_versions%ROWTYPE;s public.project_schedule_closeout_versions%ROWTYPE;q public.project_quality_closeout_versions%ROWTYPE;v public.project_variation_closeout_versions%ROWTYPE;p public.project_payment_closeout_versions%ROWTYPE;dims jsonb;score numeric;version_no integer;state text;result jsonb;BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'CONTRACTOR_SCORECARD_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_scorecard_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_management_comment,''))=''OR char_length(p_management_comment)>3000 THEN RAISE EXCEPTION'INVALID_CONTRACTOR_SCORECARD'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.contractor_scorecard.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.contractor_scorecard.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_contractor_scorecards WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'CONTRACTOR_SCORECARD_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;SELECT*INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;IF a.id IS NULL THEN RAISE EXCEPTION'CONTRACTOR_SCORECARD_REQUIRES_AWARD'USING ERRCODE='55000';END IF;SELECT*INTO c FROM public.project_cost_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT*INTO s FROM public.project_schedule_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT*INTO q FROM public.project_quality_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT*INTO v FROM public.project_variation_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;SELECT*INTO p FROM public.project_payment_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;
dims:=jsonb_build_array(jsonb_build_object('dimension','COST','score',greatest(0,100-least(100,abs(COALESCE(c.variance_to_award,0))*100/greatest(COALESCE(c.award_value,1),1))),'evidence',jsonb_build_object('varianceToAward',c.variance_to_award)),jsonb_build_object('dimension','SCHEDULE','score',greatest(0,100-least(100,greatest(COALESCE(s.completion_variance_days,0),0)*2)),'evidence',jsonb_build_object('completionVarianceDays',s.completion_variance_days)),jsonb_build_object('dimension','QUALITY','score',greatest(0,100-least(100,COALESCE(q.reopen_rate,0)+COALESCE(q.critical_snags,0)*5)),'evidence',jsonb_build_object('criticalSnags',q.critical_snags,'reopenRate',q.reopen_rate)),jsonb_build_object('dimension','VARIATIONS','score',greatest(0,100-least(100,COALESCE(v.rejected_count,0)*5+COALESCE(v.pending_count,0)*10)),'evidence',jsonb_build_object('rejected',v.rejected_count,'pending',v.pending_count)),jsonb_build_object('dimension','PAYMENT_ADMIN','score',CASE WHEN COALESCE(p.certified_value,0)=0 THEN 100 ELSE greatest(0,100-least(100,COALESCE(p.outstanding_value,0)*100/p.certified_value))END,'evidence',jsonb_build_object('outstanding',p.outstanding_value)));SELECT round(avg((x->>'score')::numeric),2)INTO score FROM jsonb_array_elements(dims)x;SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_contractor_scorecards WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_contractor_scorecards VALUES(p_scorecard_id,p_project_id,a.id,version_no,state,a.contractor_name,dims,score,btrim(p_management_comment),u,now());result:=jsonb_build_object('scorecardId',p_scorecard_id,'versionNumber',version_no,'status',state,'contractorName',a.contractor_name,'overallScore',score,'dimensions',dims);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_contractor_scorecard(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_contractor_scorecards%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'CONTRACTOR_SCORECARD_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_contractor_scorecards WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasScorecard',x.id IS NOT NULL,'scorecard',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('scorecardId',x.id,'versionNumber',x.version_number,'status',x.status,'contractorName',x.contractor_name,'dimensions',x.dimensions,'overallScore',x.overall_score,'managementComment',x.management_comment,'createdAt',x.created_at)END);END;$$;REVOKE ALL ON FUNCTION private.prevent_contractor_scorecard_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_contractor_scorecard(bigint,uuid,text,boolean,uuid),public.get_project_contractor_scorecard(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_contractor_scorecard(bigint,uuid,text,boolean,uuid),public.get_project_contractor_scorecard(bigint)TO authenticated;COMMIT;
